let allWorkers = [];
let currentOffset = 0;
const fetchLimit = 1000;
let hasMore = true;

try {
    while (hasMore) {
        const {
            entities: workers = [],
            metadata: { hasNextPage = false } = {}
        } = await this.payrollApiService.get({
            entity: "worker",
            query: `select=Id&CompanyId=${this.globalSelectedCompany.companyId}`,
            offset: currentOffset,
            limit: fetchLimit
        });

        allWorkers = allWorkers.concat(workers);

        if (hasNextPage) {
            currentOffset += fetchLimit;
        } else {
            hasMore = false;
        }
    }

    return allWorkers.map(w => w.Id);

} catch (e) {
    console.error("Error fetching Company Workers. Please try again...", e);
    throw e;
}

const displayColumnNames = [
    "Id",
    "OriginalHireDateTime",
    "SeniorityDate",
    "BirthDate",
    "IsDisabled",
    "IsFulltimeStudent",
    "MaritalStatus",
    "NumberOfDependents",
    "WorkerType",
    "WorksFromHome",
];

const displayColumnOptions = {
    type: {
        "OriginalHireDateTime": "date",
        "SeniorityDate": "date",
        "BirthDate": "date",
        "IsDisabled": "boolean",
        "IsFulltimeStudent": "boolean",
        "WorksFromHome": "boolean"
    }
}

return {
    columnKeys: displayColumnNames,
    options: displayColumnOptions
}
